module ready_valid_fifo2 #(
  parameter DATA_WIDTH = 8
) (
  input  logic                    clk,
  input  logic                    rst,
  input  logic                    in_valid,
  output logic                    in_ready,
  input  logic [DATA_WIDTH-1:0]   in_data,
  output logic                    out_valid,
  input  logic                    out_ready,
  output logic [DATA_WIDTH-1:0]   out_data
);

  // Storage registers
  logic [DATA_WIDTH-1:0] data [0:1];
  logic [1:0]            occupancy;  // 0,1,2
  logic                  head;       // 0 or 1, points to oldest valid entry

  // Combinational outputs
  assign out_valid = (occupancy != 0);
  assign out_data  = out_valid ? data[head] : {DATA_WIDTH{1'b0}};
  assign in_ready  = (occupancy < 2) || (out_valid && out_ready);

  // Input and output transfer signals
  logic input_transfer, output_transfer;
  assign input_transfer  = in_valid && in_ready;
  assign output_transfer = out_valid && out_ready;

  // Next state signals
  logic [1:0] next_occupancy;
  logic       next_head;
  logic       write_en;
  logic       write_addr;  // 0 or 1
  logic [DATA_WIDTH-1:0] write_data;

  always_comb begin
    // Default: no change
    next_occupancy = occupancy;
    next_head      = head;
    write_en       = 1'b0;
    write_addr     = 'x;
    write_data     = 'x;

    unique case ({input_transfer, output_transfer})
      2'b11: begin
        if (occupancy == 1) begin
          // Simultaneous with one entry: consume old, accept new
          // Write new input to tail slot (the empty one)
          write_addr = (head + 1) % 2;
          write_data = in_data;
          write_en   = 1'b1;
          next_head  = write_addr;  // new head is the written slot
          next_occupancy = 1;
        end else if (occupancy == 2) begin
          // Simultaneous full: consume oldest, accept new into same slot
          write_addr = head;
          write_data = in_data;
          write_en   = 1'b1;
          next_head  = (head + 1) % 2;
          next_occupancy = 2;
        end
        // occupancy == 0 impossible because output_transfer requires out_valid
      end
      2'b10: begin // input only
        if (occupancy == 0) begin
          write_addr = head;
          write_data = in_data;
          write_en   = 1'b1;
          next_head      = head;  // unchanged, only one entry
          next_occupancy = 1;
        end else if (occupancy == 1) begin
          write_addr = (head + 1) % 2;
          write_data = in_data;
          write_en   = 1'b1;
          next_head      = head;  // head unchanged
          next_occupancy = 2;
        end
        // occupancy == 2: cannot happen because in_ready would be false
      end
      2'b01: begin // output only
        if (occupancy == 1) begin
          next_occupancy = 0;
          // head unchanged (will be overwritten on next input write)
        end else if (occupancy == 2) begin
          next_occupancy = 1;
          next_head = (head + 1) % 2;
        end
        // occupancy == 0 impossible
      end
      default: ; // no transfer
    endcase
  end

  // Sequential logic
  always_ff @(posedge clk) begin
    if (rst) begin
      occupancy <= 0;
      head      <= 0;
      data[0]   <= {DATA_WIDTH{1'b0}};
      data[1]   <= {DATA_WIDTH{1'b0}};
    end else begin
      occupancy <= next_occupancy;
      head      <= next_head;
      if (write_en) begin
        data[write_addr] <= write_data;
      end
    end
  end

endmodule
